import { test } from 'node:test';
import assert from 'node:assert/strict';
import { filterAndClassify } from '../scripts/filter.mjs';
import { BASE_SCORE, EMPLOYEE_SCORE, DEFAULT_EMPLOYEE_HANDLES } from '../scripts/score.mjs';

function raw(overrides) {
  return {
    id: '1',
    author: 'somedev',
    text: 'hi @entirehq',
    url: 'https://x.com/somedev/status/1',
    createdAt: '2026-08-18T14:00:00.000Z',
    inReplyToStatusId: null,
    isQuoteStatus: false,
    ...overrides,
  };
}

test('filterAndClassify labels a plain mention', () => {
  const [t] = filterAndClassify([raw({})], 'entirehq');
  assert.equal(t.kind, 'mention');
});

test('filterAndClassify labels a reply', () => {
  const [t] = filterAndClassify([raw({ inReplyToStatusId: '999' })], 'entirehq');
  assert.equal(t.kind, 'reply');
});

test('filterAndClassify labels a reply found via the DOM sentinel', () => {
  const [t] = filterAndClassify([raw({ inReplyToStatusId: 'unknown' })], 'entirehq');
  assert.equal(t.kind, 'reply');
});

test('filterAndClassify labels a quote tweet', () => {
  const [t] = filterAndClassify([raw({ isQuoteStatus: true })], 'entirehq');
  assert.equal(t.kind, 'quote');
});

test('reply wins over quote when a tweet is both', () => {
  const [t] = filterAndClassify(
    [raw({ isQuoteStatus: true, inReplyToStatusId: '999' })],
    'entirehq',
  );
  assert.equal(t.kind, 'reply');
});

test('filterAndClassify drops posts authored by the watched account', () => {
  const tweets = filterAndClassify(
    [raw({ id: '1', author: 'entirehq' }), raw({ id: '2', author: 'somedev' })],
    'entirehq',
  );
  assert.deepEqual(tweets.map((t) => t.id), ['2']);
});

test('own-post matching ignores case and a leading @', () => {
  const tweets = filterAndClassify([raw({ author: 'EntireHQ' })], '@entirehq');
  assert.deepEqual(tweets, []);
});

test('filterAndClassify emits exactly the Tweet fields, no raw leftovers', () => {
  const [t] = filterAndClassify([raw({ inReplyToStatusId: '999' })], 'entirehq');
  assert.deepEqual(Object.keys(t).sort(), [
    'author', 'createdAt', 'id', 'isEmployee', 'kind', 'score', 'text', 'url',
  ]);
});

test('filterAndClassify sorts oldest first', () => {
  const tweets = filterAndClassify(
    [
      raw({ id: 'new', createdAt: '2026-08-18T16:00:00.000Z' }),
      raw({ id: 'old', createdAt: '2026-08-18T09:00:00.000Z' }),
    ],
    'entirehq',
  );
  assert.deepEqual(tweets.map((t) => t.id), ['old', 'new']);
});

test('filterAndClassify drops an entry missing text', () => {
  const tweets = filterAndClassify([raw({ text: undefined })], 'entirehq');
  assert.deepEqual(tweets, []);
});

test('filterAndClassify drops an entry missing url', () => {
  const tweets = filterAndClassify([raw({ url: undefined })], 'entirehq');
  assert.deepEqual(tweets, []);
});

test('filterAndClassify drops an entry missing url (empty string)', () => {
  const tweets = filterAndClassify([raw({ url: '' })], 'entirehq');
  assert.deepEqual(tweets, []);
});

test('filterAndClassify drops an entry with unparseable createdAt', () => {
  const tweets = filterAndClassify([raw({ createdAt: 'not a date' })], 'entirehq');
  assert.deepEqual(tweets, []);
});

test('filterAndClassify keeps an entry with empty text', () => {
  const [t] = filterAndClassify([raw({ text: '' })], 'entirehq');
  assert.equal(t.text, '');
});

test('filterAndClassify tolerates junk input', () => {
  assert.deepEqual(filterAndClassify(null, 'entirehq'), []);
  assert.deepEqual(filterAndClassify([null, 'nope'], 'entirehq'), []);
});

test('an outsider carries the base score and no employee flag', () => {
  const [t] = filterAndClassify([raw({ author: 'somedev' })], 'entirehq');
  assert.equal(t.score, BASE_SCORE);
  assert.equal(t.isEmployee, false);
});

test('every Entire teammate is scored down by default', () => {
  for (const handle of DEFAULT_EMPLOYEE_HANDLES) {
    const [t] = filterAndClassify([raw({ author: handle })], 'entirehq');
    assert.equal(t.score, EMPLOYEE_SCORE, `${handle} should score ${EMPLOYEE_SCORE}`);
    assert.equal(t.isEmployee, true, `${handle} should be flagged`);
  }
});

test('a teammate is still announced, not dropped', () => {
  // The trail says "take note of it", not "hide it". Scoring must never
  // become a filter by accident.
  const tweets = filterAndClassify(
    [raw({ id: '1', author: 'lizziepika' }), raw({ id: '2', author: 'somedev' })],
    'entirehq',
  );
  assert.deepEqual(tweets.map((t) => t.id).sort(), ['1', '2']);
});

test('employee scoring survives odd casing from X', () => {
  const [t] = filterAndClassify([raw({ author: 'LizziePika' })], 'entirehq');
  assert.equal(t.isEmployee, true);
});

test('an explicit roster overrides the default six', () => {
  const [ashtom] = filterAndClassify([raw({ author: 'ashtom' })], 'entirehq', ['newhire']);
  assert.equal(ashtom.isEmployee, false, 'ashtom is not on the custom roster');
  const [newhire] = filterAndClassify([raw({ author: 'newhire' })], 'entirehq', ['@NewHire']);
  assert.equal(newhire.isEmployee, true);
});

test('scoring is independent of kind', () => {
  // Only authorship moves the number, per the trail decision.
  const [reply] = filterAndClassify([raw({ author: 'ashtom', inReplyToStatusId: '9' })], 'entirehq');
  const [quote] = filterAndClassify([raw({ author: 'ashtom', isQuoteStatus: true })], 'entirehq');
  assert.equal(reply.score, EMPLOYEE_SCORE);
  assert.equal(quote.score, EMPLOYEE_SCORE);
});

test('tagging a teammate does not move an outsider score', () => {
  // Explicitly pinned: the trail title says "tagged", but the agreed rule is
  // authorship-only. A tweet mentioning @lizziepika scores like any outsider.
  const [t] = filterAndClassify(
    [raw({ author: 'somedev', text: 'hey @lizziepika does this work?' })],
    'entirehq',
  );
  assert.equal(t.score, BASE_SCORE);
  assert.equal(t.isEmployee, false);
});
# @entirehq mention watcher

Someone replies to `@entirehq` on X. You find out four hours later, because
nobody had that search tab open.

This closes that gap. A daemon polls the live `@entirehq` search every five
minutes and posts every new mention, reply, and quote tweet to Slack.

```
@somedev replied to @entirehq
> hey @entirehq does this work with self-hosted runners?
View on X · reply · score 60 · Aug 18 at 5:17 PM

@lizziepika replied to @entirehq
> yep, self-hosted runners work out of the box
View on X · reply · Entire team · score 20 · Aug 18 at 5:22 PM
```

It runs as a launchd agent — at login, across reboots, restarted if it dies,
independent of whether Claude Code is open. Zero tokens: a plain Node process
posting to a webhook, not an agent.

## Setup

```bash
npm install
cp .env.example .env       # fill in the five values below
npm run check              # one live scrape, printed, notifies nobody
npm run install-agent      # install + start the daemon
```

| Variable | Where it comes from |
| --- | --- |
| `BROWSERBASE_API_KEY` | browserbase.com → Settings |
| `BROWSERBASE_PROJECT_ID` | same page |
| `X_AUTH_TOKEN` | logged-in x.com tab → DevTools → Application → Cookies → `auth_token` |
| `X_CSRF_TOKEN` | same place → `ct0` |
| `SLACK_WEBHOOK_URL` | api.slack.com/apps → your app → Incoming Webhooks |

Optional: `X_WATCH_POLL_MS` (`300000`), `X_SEARCH_QUERY` (`@entirehq`),
`X_OWN_HANDLE` (`entirehq`).

Who counts as the team lives in **`employees.csv`**, not in `.env`. One handle
per line, `@` optional, `#` for comments, and anything after the first comma is
a free-text note:

```csv
lizziepika,Lizzie Siegle,DevRel
ashtom
```

Edit it and re-run `npm run install-agent`. No code change. A one-column file is
just a plain list, so a `.txt` of handles works verbatim. `X_EMPLOYEE_HANDLES`
overrides the file for a one-off; an empty or unreadable file falls back to the
built-in roster rather than silently un-badging everyone.

Config is read once at boot — after editing `.env`, re-run `install-agent`.

**Why cookies, not the X API.** Live search is login-gated, and API v2's
recent-search endpoint needs a paid tier (~$200/mo). Two cookies cost nothing
and last months; when they expire the watcher says so in Slack rather than
returning nothing, which would read as "nobody is mentioning us."

## How it works

```
launchd (RunAtLoad, KeepAlive) → watch.mjs
   ↓
   scrape ──→ parse ──→ filter ──→ diff ──→ post to Slack
   Browserbase   X's own    drop our    seen-id     Block Kit
   + Playwright  JSON       own posts,  store       webhook
                 (DOM        label
                  fallback)  kind, score
   ↓
   sleep 5m, repeat
```

- **Claude Code's hooks are a fallback.** `SessionStart`/`SessionEnd` run a
  session-scoped watcher only when no agent is installed for this project. With
  the agent installed they stand down, so notifications never double up.
- **Slack is the only channel.** Nothing prints to your terminal; diagnostics
  go to `.claude/entirehq-watcher/watch.log` — including when Slack is the
  thing that's broken.
- **It reads X's JSON, not the page.** Playwright intercepts the
  `SearchTimeline` response instead of scraping `data-testid` attributes X
  rotates at will. Reply/quote classification uses real fields
  (`in_reply_to_status_id`, `is_quote_status`). DOM extraction is a labelled
  fallback.
- **A teammate's post is not the same signal as a stranger's.** Posts authored
  by the Entire team (`@blackgirlbytes`, `@lizziepika`, `@evisdrenova`,
  `@ashtom`, `@jkcso`, `@HaimantikaM`) score 20; everyone else scores 60. They
  are still announced, in the same chronological order, but badged `Entire
  team` in the Slack context line and in the notification preview, so team
  chatter never reads as fresh outside interest. Only authorship moves the
  number: a stranger *tagging* a teammate scores like any other stranger. The
  roster is `employees.csv`, edited by hand, not by changing code.
- **Seen only once Slack accepts it.** Marking a failed post as seen would drop
  that mention permanently and silently; a failure costs one duplicate attempt
  next poll instead.
- **The first run notifies nobody.** It baselines whatever is already on the
  page, or day one dumps every existing mention into Slack.
- **It won't shut up about being broken.** Expired cookies, scrapes stuck at
  the 30-minute backoff cap, and three consecutive empty polls each fire
  exactly one Slack alert, deduped through the store so restarts don't
  re-alarm.

## Known limitations

- **One page per poll** — no scrolling, so roughly X's first ~20 results.
  Heavier bursts overflow; the watcher logs a note when a poll comes back that
  full. Shorter `X_WATCH_POLL_MS` reduces the risk at the cost of more sessions.
- **`X_OWN_HANDLE` suppresses one account.** Teammates' personal replies still
  notify. They are scored 20 and badged rather than hidden, which is deliberate:
  edit `employees.csv` to change who counts.
- **One agent per machine** — the launchd label is fixed. A second checkout
